/**
 * Signals in message LVCOverCurrentSnapshot.
 *
 * Latch the first overcurrent or I2T trip per output until an explicit firmware fault-reset action. Freeze the last pre-trip current, its age at detection and the sending board monotonic uptime at detection. Reading diagnostic registers does not clear the telemetry latch. Send immediately on a new trip, then every 1000 ms while a trip remains latched. Never overwrite a captured current with post-shutdown zero. No snapshot/event identifier is sent. Capture time resets on board reboot. This records a sampled current, not a guaranteed instantaneous analog peak.
 *
 * All signal values are as on the CAN bus.
 */
struct car_can_raw_lvc_over_current_snapshot_t {
    /**
     * Latched OverCurrent trip for BPS feed.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint8_t fault_over_current;

    /**
     * Latched I2T trip for BPS feed.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint8_t fault_i2_t;

    /**
     * 1 if the captured current is clipped or the sensing path was saturated; the current is then a lower bound, not an exact peak.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint8_t trip_current_saturated;

    /**
     * Board uptime at the first latched trip; wraps at 2^32 ms. Interpret only while a trip flag is set.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint32_t capture_time_ms;

    /**
     * Captured current; independent record per output; saturation marks a lower bound.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint16_t trip_current;

    /**
     * Age in milliseconds of the oldest continuous sensor sample included in this frame when assembled; saturates at 65535. Age must advance for cached samples. In a fault snapshot, freeze age at fault detection; per-channel captured ages, if present, remain authoritative for individual trip records.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint16_t sample_age_ms;
};

